-- Cars and Coffee UK website content, now in the Cars and Coffee Community project (schema "site").
-- Moved from the Race Car Graphics CRM "cac" schema on 2026-11-22. Seed: supabase/seed_homepage.sql (generated by tools/build.py).
create schema if not exists site;
comment on schema site is 'Cars and Coffee UK website content: homepage blocks, events, news, shop, partners, directory, ads, newsletter, SEO pages.';


create table site.homepage_blocks (
  key text primary key,
  title text not null,
  position int not null,
  enabled boolean not null default true,
  starts_at timestamptz,
  ends_at timestamptz,
  settings jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
comment on table site.homepage_blocks is 'Order, on/off and schedule of each homepage block; the admin drag-and-drop list edits this.';

create table site.events (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  title text not null,
  event_type text not null check (event_type in ('meet','tour','garage','watch','track','show','race')),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  venue text not null,
  region text,
  price_pence int not null default 0,
  ticket_status text not null default 'on_sale' check (ticket_status in ('free_rsvp','on_sale','selling_fast','sold_out')),
  members_only boolean not null default false,
  image_path text,
  image_alt text,
  published boolean not null default true,
  created_at timestamptz not null default now()
);

create table site.articles (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  title text not null,
  category text not null,
  excerpt text,
  body text,
  image_path text,
  image_alt text,
  read_minutes int,
  featured boolean not null default false,
  status text not null default 'published' check (status in ('draft','published')),
  published_at date not null default current_date
);

create table site.community_highlights (
  id uuid primary key default gen_random_uuid(),
  handle text not null,
  title text not null,
  excerpt text,
  image_path text,
  image_alt text,
  post_url text,
  sort int not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
comment on table site.community_highlights is 'Hand-picked public community posts for the homepage until the community app feeds this directly.';

create table site.products (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  price_pence int not null,
  member_price_pence int,
  badge text,
  image_path text,
  image_alt text,
  units_sold_30d int not null default 0,
  partner_id uuid,
  active boolean not null default true
);

create table site.gallery_items (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  title text not null,
  image_path text not null,
  image_alt text not null,
  sort int not null default 0,
  featured boolean not null default true
);

create table site.directory_regions (id serial primary key, name text unique not null, slug text unique not null, sort int not null default 0);
create table site.directory_services (id serial primary key, name text unique not null, slug text unique not null, sort int not null default 0);
create table site.directory_listings (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  services text[] not null default '{}',
  town text,
  region text,
  website text,
  image_path text,
  image_alt text,
  featured boolean not null default false,
  featured_until date,
  status text not null default 'published' check (status in ('pending','published','rejected')),
  created_at timestamptz not null default now()
);
create table site.directory_contacts (
  listing_id uuid primary key references site.directory_listings(id) on delete cascade,
  contact_name text, email text, phone text, notes text
);
comment on table site.directory_contacts is 'Business contact details, team only (never public).';

create table site.partners (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  tagline text,
  page_path text,
  logo_path text,
  sort int not null default 0,
  active boolean not null default true
);
alter table site.products add constraint products_partner_fk foreign key (partner_id) references site.partners(id);

create table site.partner_features (
  id uuid primary key default gen_random_uuid(),
  partner_id uuid not null references site.partners(id),
  block_key text not null references site.homepage_blocks(key),
  title text not null,
  body text,
  extra text,
  image_path text,
  image_alt text,
  cta_label text, cta_url text,
  cta2_label text, cta2_url text,
  countdown_to timestamptz,
  starts_at timestamptz not null default now(),
  ends_at timestamptz,
  active boolean not null default true
);
comment on column site.partner_features.countdown_to is 'Le Mans 2027 race start set to 12 June 2027 16:00 local (start time to be confirmed by the ACO).';

create table site.sponsored_slots (
  id uuid primary key default gen_random_uuid(),
  advertiser text not null,
  title text not null,
  body text,
  image_path text,
  image_alt text,
  cta_label text,
  cta_url text,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status text not null default 'approved' check (status in ('pending','approved','rejected','paused')),
  impressions bigint not null default 0,
  clicks bigint not null default 0
);

create table site.faqs (id serial primary key, question text not null, answer text not null, sort int not null default 0, published boolean not null default true);

create table site.site_stats (key text primary key, label text not null, value text not null, is_sample boolean not null default false, updated_at timestamptz not null default now());

create table site.newsletter_subscribers (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  consent boolean not null check (consent),
  consent_text text not null default 'I’d like to receive emails from Cars and Coffee UK, including events, news and partner offers.',
  source text not null default 'homepage',
  created_at timestamptz not null default now(),
  unsubscribed_at timestamptz
);
create unique index newsletter_subscribers_email_key on site.newsletter_subscribers (lower(email));


-- SEO and Google Ads pages (locations, sectors, audiences, guides, landing pages) edited in admin.carsandcoffee.uk
create table site.pages (
  id uuid primary key default gen_random_uuid(),
  path text unique not null check (path ~ '^/[a-z0-9/-]*$'),
  page_type text not null default 'standard' check (page_type in ('standard','location','sector','audience','guide','landing')),
  title text not null,
  h1 text,
  meta_title text,
  meta_description text,
  focus_keyword text,
  secondary_keywords text[] not null default '{}',
  intro text,
  body_md text,
  hero_image_path text,
  hero_image_alt text,
  og_image_path text,
  canonical_url text,
  noindex boolean not null default false,
  schema_type text not null default 'WebPage',
  county text,
  town text,
  parent_id uuid references site.pages(id) on delete set null,
  cta_label text,
  cta_url text,
  ads jsonb not null default '{}'::jsonb,
  seo_score int,
  status text not null default 'draft' check (status in ('draft','review','published','archived')),
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles(id) on delete set null
);
comment on column site.pages.ads is 'Google Ads details for landing pages: campaign, ad_group, keywords[], headlines[] (max 30 chars), descriptions[] (max 90 chars), utm_source/medium/campaign.';
create index pages_type_idx on site.pages (page_type, status);

create table site.page_revisions (
  id bigint generated always as identity primary key,
  page_id uuid not null references site.pages(id) on delete cascade,
  snapshot jsonb not null,
  saved_by uuid references public.profiles(id) on delete set null,
  saved_at timestamptz not null default now()
);

create or replace function site.touch_page() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  new.updated_at := now(); new.updated_by := auth.uid();
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then new.published_at := coalesce(new.published_at, now()); end if;
  if tg_op = 'UPDATE' then insert into site.page_revisions (page_id, snapshot, saved_by) values (old.id, to_jsonb(old), auth.uid()); end if;
  return new;
end; $$;
create trigger pages_touch before insert or update on site.pages for each row execute function site.touch_page();

-- Row level security: the public reads published content; the club team (admins and moderators) can edit everything.
do $$ declare t text; begin
  foreach t in array array['homepage_blocks','events','articles','community_highlights','products','gallery_items','directory_regions','directory_services','directory_listings','directory_contacts','partners','partner_features','sponsored_slots','faqs','site_stats','newsletter_subscribers','pages','page_revisions'] loop
    execute format('alter table site.%I enable row level security', t);
    execute format('create policy "team manage" on site.%I for all to authenticated using ((select private.is_moderator())) with check ((select private.is_moderator()))', t);
  end loop; end $$;

create policy "public read" on site.homepage_blocks for select to anon, authenticated using (enabled and (starts_at is null or starts_at <= now()) and (ends_at is null or ends_at > now()));
create policy "public read" on site.events for select to anon, authenticated using (published);
create policy "public read" on site.articles for select to anon, authenticated using (status = 'published' and published_at <= current_date);
create policy "public read" on site.community_highlights for select to anon, authenticated using (active);
create policy "public read" on site.products for select to anon, authenticated using (active);
create policy "public read" on site.gallery_items for select to anon, authenticated using (featured);
create policy "public read" on site.directory_regions for select to anon, authenticated using (true);
create policy "public read" on site.directory_services for select to anon, authenticated using (true);
create policy "public read" on site.directory_listings for select to anon, authenticated using (status = 'published');
create policy "public read" on site.partners for select to anon, authenticated using (active);
create policy "public read" on site.partner_features for select to anon, authenticated using (active and starts_at <= now() and (ends_at is null or ends_at > now()));
create policy "public read" on site.sponsored_slots for select to anon, authenticated using (status = 'approved' and starts_at <= now() and ends_at > now());
create policy "public read" on site.faqs for select to anon, authenticated using (published);
create policy "public read" on site.site_stats for select to anon, authenticated using (true);
create policy "public read" on site.pages for select to anon, authenticated using (status = 'published');
create policy "public sign up" on site.newsletter_subscribers for insert to anon, authenticated with check (consent and unsubscribed_at is null);

grant usage on schema site to anon, authenticated, service_role;
grant select on all tables in schema site to anon;
grant select, insert, update, delete on all tables in schema site to authenticated;
grant usage, select on all sequences in schema site to authenticated, service_role;
grant all on all tables in schema site to service_role;
revoke select on site.newsletter_subscribers, site.directory_contacts, site.page_revisions from anon;
grant insert (email, consent, source) on site.newsletter_subscribers to anon;
